"""Component 3 - a vocabulary that grows and prunes itself.

DDO's orthogonality regularizer (clip_cbm_orth) is built from a fixed,
204-entry pool of hand-authored text templates
(prompts/prompt200new.py's target_text_prompts) - written once, never
updated. Phase E1 found zero terms in that pool for any post-cutoff
AI-image-generation domain; Phase E2 measured the cost (DDO's benefit
collapses from +6.40 to +0.68 points without coverage).

Nothing in clip_cbm_orth's forward pass requires this pool be fixed size or
fixed content - it only ever does `self.diffs @ self.concept_embeddings.T`,
and the leading (num_directions) dimension is averaged away in the
orthogonality loss. This module adds two operations on top of that same
pool: growth (add new templates for a domain the pool doesn't cover yet,
filtered by whether they actually measure as connected to the domain) and
pruning (drop redundant templates so the pool doesn't grow without bound).

Deliberate substitution, flagged per this project's convention (see Phase
E1's own choice to avoid a fresh paid GPT-3.5 call): candidate templates
are generated by cheap, deterministic string patterns filled with the
arriving domain's own name, not by a live LLM call. Growth only accepts a
candidate if it's independently measured (via Component 2's
alignment-score formula, reused rather than reinvented) to actually
connect to real probe images of the domain - so a low-quality generated
phrase can't get in just for existing.
"""
import torch
import clip

from model.domain_grounding import _encode_text_template, _mean_image_embeddings_by_class


CANDIDATE_TEMPLATE_PATTERNS = [
    "a {domain} image of a {{}}.",
    "a {domain}-style image of a {{}}.",
    "an AI-generated {domain} image of a {{}}.",
    "a {domain} rendering of a {{}}.",
    "a synthetic {domain} image of a {{}}.",
    "a photorealistic {domain} image of a {{}}.",
    "a generative AI {domain} image of a {{}}.",
    "a {domain} generated picture of a {{}}.",
    "a computer-generated {domain} image of a {{}}.",
    "an artificial {domain} rendering of a {{}}.",
]


def generate_candidate_descriptors(domain_name):
    """Fills CANDIDATE_TEMPLATE_PATTERNS with domain_name, leaving the
    class-name {} placeholder intact for later .format(class_name) calls -
    same convention as prompt200new.py's target_text_prompts."""
    return [pattern.format(domain=domain_name) for pattern in CANDIDATE_TEMPLATE_PATTERNS]


def score_candidate_descriptors(clip_model, candidates, source_images_by_class,
                                 target_images_by_class, class_names, source_template,
                                 device, preprocess=None):
    """Alignment score per candidate template, using Component 2's exact
    formula (visual shift from the probe vs. textual shift from the
    candidate template), reusing the same probe images already drawn for
    the trust diagnostic - no extra data collection.

    Returns dict[candidate_template] = mean_alignment (float).
    """
    src_text_emb = _encode_text_template(clip_model, source_template, class_names, device)
    if source_images_by_class is None:
        src_img_emb = src_text_emb
    else:
        src_img_emb = _mean_image_embeddings_by_class(clip_model, source_images_by_class, class_names, device, preprocess)
    tgt_img_emb = _mean_image_embeddings_by_class(clip_model, target_images_by_class, class_names, device, preprocess)

    scores = {}
    for candidate in candidates:
        tgt_text_emb = _encode_text_template(clip_model, candidate, class_names, device)
        per_class = []
        for i in range(len(class_names)):
            visual_shift = tgt_img_emb[i] - src_img_emb[i]
            visual_shift = visual_shift / visual_shift.norm()
            textual_shift = tgt_text_emb[i] - src_text_emb[i]
            textual_shift = textual_shift / textual_shift.norm()
            per_class.append(torch.dot(visual_shift, textual_shift).item())
        scores[candidate] = sum(per_class) / len(per_class)
    return scores


def grow_descriptor_pool(clip_model, existing_pool, domain_name, source_images_by_class,
                          target_images_by_class, class_names, source_template, threshold,
                          device, preprocess=None, max_new=None):
    """Generates candidates for domain_name, scores them against the probe,
    and returns a NEW pool (existing_pool + accepted candidates, existing
    entries never removed here - that's prune_redundant_descriptors's job).

    Returns (new_pool, accepted: dict[str,float], rejected: dict[str,float]).
    A candidate is accepted iff its alignment score >= threshold AND it's
    not already an exact string match in existing_pool.
    """
    candidates = generate_candidate_descriptors(domain_name)
    scores = score_candidate_descriptors(
        clip_model, candidates, source_images_by_class, target_images_by_class,
        class_names, source_template, device, preprocess,
    )
    existing_set = set(existing_pool)
    accepted, rejected = {}, {}
    for candidate, score in scores.items():
        if candidate in existing_set:
            rejected[candidate] = score
            continue
        if score >= threshold:
            accepted[candidate] = score
        else:
            rejected[candidate] = score

    ordered_accepted = sorted(accepted.items(), key=lambda kv: -kv[1])
    if max_new is not None:
        ordered_accepted = ordered_accepted[:max_new]
        for candidate, score in accepted.items():
            if (candidate, score) not in ordered_accepted:
                rejected.setdefault(candidate, score)
        accepted = dict(ordered_accepted)

    new_pool = list(existing_pool) + [c for c, _ in ordered_accepted]
    return new_pool, accepted, rejected


def prune_redundant_descriptors(clip_model, pool, device, redundancy_threshold=0.97,
                                 placeholder="object", protected_prefix_len=None):
    """Drops later-added pool entries that are near-duplicates (by text
    embedding cosine similarity) of an earlier-kept entry - keeps the pool
    bounded as growth adds more templates across domains.

    Each template is embedded with a neutral placeholder noun filled in
    (not per-class - pruning is about the template's own semantic content,
    independent of which class it's later applied to). Entries are scanned
    in order and an entry is dropped iff it's within redundancy_threshold
    cosine similarity of some earlier-kept entry - so entries at the front
    of the list (by convention, the original 204-entry pool, since growth
    only ever appends) are always preferred over later, grown duplicates.

    protected_prefix_len: if given, the first N entries (e.g. the original
    204-entry pool) are never dropped, only ever compared against as
    keepers - only entries at index >= N can be pruned. Defaults to None
    (every entry, including originals, can in principle be pruned against
    an even-earlier duplicate; in practice the original pool has no
    near-duplicates of itself, per Phase E1, so this rarely matters).

    Returns (kept_pool: list[str], dropped: list[str]).
    """
    texts = clip.tokenize([t.format(placeholder) for t in pool]).to(device)
    with torch.no_grad():
        emb = clip_model.encode_text(texts).float()
    emb = emb / emb.norm(dim=-1, keepdim=True)

    kept_idx = []
    dropped = []
    for i, template in enumerate(pool):
        is_protected = protected_prefix_len is not None and i < protected_prefix_len
        redundant = False
        if not is_protected and kept_idx:
            sims = (emb[kept_idx] @ emb[i]).tolist()
            redundant = max(sims) >= redundancy_threshold
        if redundant:
            dropped.append(template)
        else:
            kept_idx.append(i)

    kept_pool = [pool[i] for i in kept_idx]
    return kept_pool, dropped
